"use client";

import * as Sentry from "@sentry/nextjs";
import Image from "next/image";
import { useEffect, useState } from "react";
import StarIcon from "../../../public/icons/StarIcon";
import { getSuppliers } from "@/services/suppliers";

export default function Page() {
  const [operators, setOperators] = useState([]);
  const [spinner, setSpinner] = useState(false);
  const [filteredOperators, setFilteredOperators] = useState([]);
  const [alphabet, setAlphabet] = useState<string[]>([]);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 50;

  useEffect(() => {
    const fetchData = async () => {
      setSpinner(true);
      try {
        const data = await getSuppliers();
        setOperators(data);
        setFilteredOperators(data);
        generateAlphabet(data);
      } catch (error) {
        Sentry.captureException(error);
      }
      setSpinner(false);
    };

    fetchData();
  }, []);

  const generateAlphabet = (data: any) => {
    const letters: string[] = [];

    data.forEach((operator: any) => {
      const firstLetter = operator.name.charAt(0).toUpperCase();
      letters.push(firstLetter);
    });

    const sortedLetters: string[] = Array.from(new Set(letters)).sort();
    setAlphabet(sortedLetters);
  };

  const showAll = () => {
    setFilteredOperators(operators);
  };

  const filterByLetter = (letter: any) => {
    const filtered = operators.filter(
      (operator: any) => operator.name.charAt(0).toUpperCase() === letter,
    );
    setFilteredOperators(filtered);
    setCurrentPage(1); // Reset to the first page when changing the filter
  };

  const sortedItems = filteredOperators
    .slice()
    .sort((a: any, b: any) => b.tourcount - a.tourcount);

  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = sortedItems.slice(indexOfFirstItem, indexOfLastItem);

  const paginate = (pageNumber: any) => setCurrentPage(pageNumber);

  return (
    <>
      {spinner ? (
        <div
          className="tw-mx-auto tw-mt-[70px] tw-mb-5 tw-block tw-w-12 tw-h-12 tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent tw-animate-spin"
          role="status"
        ></div>
      ) : (
        <div className="tw-font-display">
          <div className="tw-flex tw-flex-wrap tw-items-center tw-gap-2 tw-p-5">
            <button
              type="button"
              className="tw-text-2xl tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#14101c] hover:tw-text-[#854ec9] tw-transition-colors"
              onClick={showAll}
            >
              All
            </button>
            {alphabet.map((letter) => (
              <button
                type="button"
                className="tw-px-2 tw-py-1 tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#5d556c] hover:tw-text-[#854ec9] tw-transition-colors"
                key={letter}
                onClick={() => filterByLetter(letter)}
              >
                {letter}
              </button>
            ))}
          </div>
          <div className="tw-max-w-[1320px] tw-mx-auto tw-px-1 md:tw-px-5">
            <h2 className="tw-text-[24px] tw-font-bold tw-text-center tw-text-[#2d055e]">
              Our Suppliers
            </h2>
            <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-4 tw-mt-4">
              {currentItems.map((supplier: any, index) => (
                <a
                  href={"/suppliers/" + supplier.slug}
                  className="tw-no-underline"
                  key={index}
                >
                  <div className="tw-flex tw-items-center tw-gap-3 tw-h-full tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-shadow-sm hover:tw-shadow-md tw-transition-shadow tw-p-3">
                    <div className="tw-shrink-0 tw-w-[100px] tw-flex tw-items-center tw-justify-center">
                      {supplier.logo && (
                        <Image
                          src={supplier.logo ? supplier.logo : ""}
                          alt={supplier.name}
                          width={100}
                          height={80}
                          onError={(e: any) =>
                            (e.target.srcset = "/images/no-profile.png")
                          }
                        />
                      )}
                    </div>
                    <div className="tw-min-w-0">
                      <p className="tw-text-[17px] tw-font-semibold tw-text-[#14101c] tw-m-0 tw-truncate">
                        {supplier.name}
                      </p>
                      <p className="tw-text-[14px] tw-text-[#5d556c] tw-m-0 tw-mt-1 tw-flex tw-items-center tw-gap-1">
                        <StarIcon /> 5<small>/5</small> - {supplier.tourcount}{" "}
                        Tour(s)
                      </p>
                    </div>
                  </div>
                </a>
              ))}
            </div>
          </div>

          <div className="tw-flex tw-flex-wrap tw-justify-center tw-gap-1 tw-w-fit tw-mx-auto tw-my-5">
            {Array.from({
              length: Math.ceil(sortedItems.length / itemsPerPage),
            }).map((_, index) => (
              <button
                className={`tw-min-w-[40px] tw-px-3 tw-py-2 tw-rounded-lg tw-border tw-border-solid tw-cursor-pointer tw-transition-colors ${
                  currentPage === index + 1
                    ? "tw-bg-[#854ec9] tw-text-white tw-border-[#854ec9]"
                    : "tw-bg-white tw-text-[#14101c] tw-border-[#d6d2de] hover:tw-border-[#854ec9]"
                }`}
                key={index}
                onClick={() => paginate(index + 1)}
              >
                {index + 1}
              </button>
            ))}
          </div>
        </div>
      )}
    </>
  );
}
